// Opponent-only legacy templates were never designed to become free agents.
 // Give them valid market terms before AI agencies can hire or release them.
 // Keep D.FOES and all original character IDs unchanged for old saves.
const oldOpponents=D.FOES.map(w=>{
 const heat=w.heat??40;
 const tier=heat>=65?'Star':heat>=52?'Veteran':'Prospect';
 return {...w,tier,handle:w.handle||w.name,
  fee:Math.max(530,Math.round((w.ring*12+heat*5)/10)*10),
  wage:Math.max(110,Math.round((w.ring*2.35+heat*.5)/5)*5),
  mic:w.mic??Math.round((w.psych+heat)/2),
  loyal:w.loyal??Math.round(w.pro*.7+15),
  morale:w.morale??65,fatigue:w.fatigue??0,
  bio:w.bio||w.name+' is a '+w.style.toLowerCase()+' specialist who works the regional circuit.'
 };
});
const existing=[...D.TALENT,...oldOpponents],seen=new Set(existing.map(w=>w.id));
const extra=newCast.map(w=>{
 if(seen.has(w.id))throw Error('Duplicate wrestler ID '+w.id);
 seen.add(w.id);
 return {...w,heat:defaults[w.tier]??35,morale:72,fatigue:0,sub:w.style==='Technical'};
});
if(seen.size!==80)throw Error('Expected 80 unique wrestlers');
